function evnt_save_meta_box( $post_id ) {
    // Verificación de seguridad y permisos
    if ( ! isset( $_POST['evnt_meta_nonce'] ) || ! wp_verify_nonce( sanitize_text_field( wp_unslash( $_POST['evnt_meta_nonce'] ) ), 'evnt_save_meta_box' ) ) {
        return;
    }
    if ( ! current_user_can( 'edit_post', $post_id ) ) {
        return;
    }
    if ( defined( 'DOING_AUTOSAVE' ) && DOING_AUTOSAVE ) {
        return;
    }

    // Sanitización y validación de inputs
    $fecha = isset( $_POST['evnt_fecha'] ) ? sanitize_text_field( wp_unslash( $_POST['evnt_fecha'] ) ) : '';
    $lugar = isset( $_POST['evnt_lugar'] ) ? sanitize_text_field( wp_unslash( $_POST['evnt_lugar'] ) ) : '';
    $precio = isset( $_POST['evnt_precio'] ) ? floatval( sanitize_text_field( wp_unslash( $_POST['evnt_precio'] ) ) ) : 0.00;

    // Validación básica de fecha
    if ( ! empty( $fecha ) && date_create_from_format( 'Y-m-d', $fecha ) === false ) {
        add_settings_error( 'evnt_save_error', 'invalid_date', __( 'Formato de fecha inválido.', 'eventos-pro' ), 'error' );
        return;
    }

    // Actualizar metadatos
    update_post_meta( $post_id, '_evnt_fecha', $fecha );
    update_post_meta( $post_id, '_evnt_lugar', $lugar );
    update_post_meta( $post_id, '_evnt_precio', $precio );
}
add_action( 'save_post_eventos', 'evnt_save_meta_box', 10, 2 );

/* ==========================================================================
