class Evnt_Admin_List_Table extends WP_List_Table {
    public function __construct() {
        parent::__construct( array(
            'singular' => 'evento',
            'plural'   => 'eventos',
            'ajax'     => false,
        ) );
    }

    public function get_columns() {
        return array(
            'cb'         => '<input type="checkbox" />',
            'titulo'     => __( 'Título', 'eventos-pro' ),
            'fecha'      => __( 'Fecha', 'eventos-pro' ),
            'lugar'      => __( 'Lugar', 'eventos-pro' ),
            'precio'     => __( 'Precio', 'eventos-pro' ),
            'categoria'  => __( 'Categoría', 'eventos-pro' ),
        );
    }

    public function get_sortable_columns() {
        return array(
            'titulo'  => array( 'title', false ),
            'fecha'   => array( '_evnt_fecha', true ),
        );
    }

    public function column_default( $item, $column_name ) {
        switch ( $column_name ) {
            case 'fecha':
                return ! empty( $item['fecha'] ) ? esc_html( $item['fecha'] ) : '<span class="dashicons dashicons-no-alt"></span>';
            case 'lugar':
                return ! empty( $item['lugar'] ) ? esc_html( $item['lugar'] ) : '-';
            case 'precio':
                return ! empty( $item['precio'] ) && floatval( $item['precio'] ) > 0 
                    ? wc_price( floatval( $item['precio'] ) ) 
                    : __( 'Gratis', 'eventos-pro' );
            case 'categoria':
                return ! empty( $item['categorias'] ) ? esc_html( implode( ', ', $item['categorias'] ) ) : '-';
            default:
                return '';
        }
    }

    public function column_cb( $item ) {
        return sprintf( '<label class="screen-reader-text" for="cb-select-%1$s">%2$s</label><input type="checkbox" name="_evnt_bulk[%1$s]" value="%1$s" />', absint( $item['ID'] ), esc_attr__( 'Seleccionar', 'eventos-pro' ) );
    }

    public function column_titulo( $item ) {
        $actions = array(
            'edit'   => sprintf( '<a href="%s">%s</a>', get_edit_post_link( absint( $item['ID'] ) ), __( 'Editar', 'eventos-pro' ) ),
            'trash'  => sprintf( '<a href="%s">%s</a>', wp_nonce_url( admin_url( "post.php?action=trash&post={$item['ID']}" ), 'trash-post_' . absint( $item['ID'] ) ), __( 'Papelera', 'eventos-pro' ) ),
        );
        return sprintf( '<strong>%s</strong> %s', esc_html( $item['title'] ), $this->row_actions( $actions, true ) );
    }

    public function prepare_items() {
        $per_page     = 20;
        $current_page = $this->get_pagenum();
        $orderby      = isset( $_GET['orderby'] ) ? sanitize_text_field( wp_unslash( $_GET['orderby'] ) ) : 'date';
        $order        = isset( $_GET['order'] ) ? sanitize_text_field( wp_unslash( $_GET['order'] ) ) : 'desc';

        // Query de eventos
        $query_args = array(
            'post_type'      => 'eventos',
            'posts_per_page' => $per_page,
            'paged'          => $current_page,
            'orderby'        => 'meta_value',
            'order'          => $order,
            'meta_key'       => '_evnt_fecha',
            'post_status'    => array( 'publish', 'draft', 'pending' ),
        );

        if ( $orderby === 'title' ) {
            unset( $query_args['meta_key'] );
            $query_args['orderby'] = 'title';
        }

        $events_query = new WP_Query( $query_args );

        // Mapeo de datos
        $this->items = array();
        foreach ( $events_query->posts as $post ) {
            $this->items[] = array(
                'ID'         => absint( $post->ID ),
                'title'      => get_the_title( $post->ID ),
                'fecha'      => get_post_meta( $post->ID, '_evnt_fecha', true ),
                'lugar'      => get_post_meta( $post->ID, '_evnt_lugar', true ),
                'precio'     => get_post_meta( $post->ID, '_evnt_precio', true ),
                'categorias' => wp_get_object_terms( $post->ID, 'categorias-evento', array( 'fields' => 'names' ) ),
            );
        }

        // Configuración de paginación
        $total_items = $events_query->found_posts;
        $this->set_pagination_args( array(
            'total_items' => $total_items,
            'per_page'    => $per_page,
        ) );
    }
}

