/* ==========================================================================
   SHORTCODE [eventos_proximos]
   ========================================================================== */
function evnt_shortcode_proximos( $atts ) {
    // Parseo y validación de atributos
    $atts = shortcode_atts( array(
        'limit' => 5,
        'order' => 'ASC',
        'class' => '',
    ), $atts, 'eventos_proximos' );

    $limit   = absint( $atts['limit'] );
    $order   = in_array( strtoupper( sanitize_text_field( wp_unslash( $atts['order'] ) ), array( 'ASC', 'DESC' ), true ) ? strtoupper( sanitize_text_field( wp_unslash( $atts['order'] ) ) ) : 'ASC';
    $css_class = esc_attr( sanitize_text_field( wp_unslash( $atts['class'] ) ) );

    // Consultar eventos próximos
    $today = current_time( 'Y-m-d' );
    $query = new WP_Query( array(
        'post_type'      => 'eventos',
        'posts_per_page' => $limit,
        'post_status'    => 'publish',
        'meta_key'       => '_evnt_fecha',
        'orderby'        => 'meta_value',
        'order'          => $order,
        'meta_query'     => array(
            array(
                'key'     => '_evnt_fecha',
                'value'   => $today,
                'compare' => '>=',
                'type'    => 'DATE',
            ),
        ),
        'no_found_rows'  => false, // Necesario para paginación
    ) );

    if ( ! $query->have_posts() ) {
        return '<p class="evnt-empty">' . esc_html__( 'No hay eventos próximos programados.', 'eventos-pro' ) . '</p>';
    }

    ob_start();
    ?>
    <div class="evnt-shortcode-wrapper <?php echo $css_class; ?>">
        <ul class="evnt-list">
        <?php while ( $query->have_posts() ) : $query->the_post();
            $fecha = get_post_meta( get_the_ID(), '_evnt_fecha', true );
            $lugar = get_post_meta( get_the_ID(), '_evnt_lugar', true );
            $precio = get_post_meta( get_the_ID(), '_evnt_precio', true );
        ?>
            <li class="evnt-item">
                <h3 class="evnt-title"><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h3>
                <dl class="evnt-details">
                    <dt><?php esc_html_e( 'Fecha:', 'eventos-pro' ); ?></dt>
                    <dd><?php echo esc_html( $fecha ? date_i18n( get_option( 'date_format' ), strtotime( $fecha ) ) : '' ); ?></dd>

                    <dt><?php esc_html_e( 'Lugar:', 'eventos-pro' ); ?></dt>
                    <dd><?php echo esc_html( $lugar ?: '-' ); ?></dd>

                    <dt><?php esc_html_e( 'Precio:', 'eventos-pro' ); ?></dt>
                    <dd><?php echo ! empty( $precio ) && floatval( $precio ) > 0 ? esc_html( wc_price( floatval( $precio ) ) ) : esc_html__( 'Gratis', 'eventos-pro' ); ?></dd>
                </dl>
            </li>
        <?php endwhile; wp_reset_postdata(); ?>
        </ul>

        <?php 
        // Paginación
        if ( $query->max_num_pages > 1 ) :
            $big = 999999999;
            echo paginate_links( array(
                'base'      => str_replace( $big, '%#%', esc_url( get_pagenum_link( $big ) ) ),
                'format'    => '?paged=%#%',
                'current'   => max( 1, get_query_var( 'paged' ) ),
                'total'     => $query->max_num_pages,
                'prev_text' => '&laquo;',
                'next_text' => '&raquo;',
            ) );
        endif;
        ?>
    </div>
    <?php
    return ob_get_clean();
}
add_shortcode( 'eventos_proximos', 'evnt_shortcode_proximos' );

